function renderControl(){
 const agents=visibleAgents(),needs=scopeAgents().filter(a=>a.status==='needs');
 const groups=[...new Set(agents.map(a=>a.project))],scoped=scopeAgents(),handoff=scoped.some(a=>a.id==='navigation'),recent=scoped.filter(a=>a.status==='done');
 return frame(1,`<section class="control-layout"><div class="control-main"><div class="page-heading"><div><p class="overline">${tr('全局在手 · 执行并行','FULL CONTEXT · PARALLEL EXECUTION')}</p><h2>${tr('把方向说清，剩下的交给团队。','One direction. A team in motion.')}</h2></div><div class="live-count"><strong>${scopeAgents().length.toString().padStart(2,'0')}</strong><span>AGENTS</span></div></div>${directiveBox()}<div class="section-bar"><h3>${tr('执行中的团队','Your team at work')}</h3><div class="filter-buttons">${['all','running','needs'].map(f=>`<button data-agent-filter="${f}" aria-pressed="${S().filter===f}">${t(f)}</button>`).join('')}</div></div><div class="project-groups">${groups.map(p=>`<section class="project-block"><header>${icon('folder')}<h3>${projects[p].name}</h3><span>${agents.filter(a=>a.project===p).length} Agent</span></header><div class="agent-grid">${agents.filter(a=>a.project===p).map(a=>agentCard(a)).join('')}</div></section>`).join('')||`<p class="empty">${t('empty')}</p>`}</div></div><aside class="control-aside"><div class="aside-title"><span class="attention-dot"></span><h3>${tr('需要你指挥','Your direction needed')}</h3><b>${needs.length}</b></div>${needs.map(a=>`<article class="attention-card"><div>${av(a)}<strong>${a.agent}</strong><span>${a.engine}</span></div><h3>${esc(l(a.title))}</h3><p>${esc(l(a.recommendation))}</p><button class="button" data-review="${a.id}">${tr('看建议，做决定','Review the recommendation')}${icon('arrow')}</button></article>`).join('')}<div class="quiet-block"><span class="overline">${tr('Norma 正在留意','NORMA IS WATCHING')}</span><p>${handoff?tr('发布说明在等桌面验收。Jasper 的结果确认后，可以交给 Echo 接力。','Release notes depend on desktop review. After Jasper’s review, Echo can take over.'):tr('正在跟进当前范围内的工作。你可以直接打开任一 Agent 的会话，调整下一步方向。','Following work in this scope. Open an agent’s conversation to adjust its next step.')}</p>${handoff?`<button class="text-button" data-handoff="navigation">${tr('安排一次交接','Arrange a handoff')}${icon('link')}</button>`:''}</div><div class="mini-roster"><h4>${tr('最近交付','Recent delivery')}</h4>${recent.map(a=>rosterRow(a,icon('check'))).join('')||`<p class="small-note">${tr('当前范围还没有新的交付','No new delivery in this scope')}</p>`}</div></aside></section>`);
}
